list_tax_profiles.code:
var response = await client.TaxProfiles.ListTaxProfilesAsync(
    new Dictionary<string, object?> { ["limit"] = 20 });
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
foreach (var taxProfile in ((IReadOnlyList<object?>)body["tax_profiles"]!).Cast<IReadOnlyDictionary<string, object?>>())
    Console.WriteLine($"{taxProfile["id"]} {taxProfile["name"]} {taxProfile["default"]}");

create_tax_profile.code:
var response = await client.TaxProfiles.CreateTaxProfileAsync(new Dictionary<string, object?>
{
    ["tax_profile"] = new Dictionary<string, object?> { ["name"] = "Wholesale", ["description"] = "Profile for wholesale customers" },
});
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
var taxProfile = (IReadOnlyDictionary<string, object?>)body["tax_profile"]!;
Console.WriteLine(taxProfile["id"]);

